#include <iostream>
#include <string>

class GuardedAccount {
public:
    explicit GuardedAccount(int initialBalance)
        : balance(initialBalance) {
        std::cout << "Account ctor: balance = " << balance << "\n";
    }

    ~GuardedAccount() {
        std::cout << "Account dtor: balance = " << balance << "\n";
    }

    // Safe: returns value or const reference
    int getBalance() const { return balance; }

    // Dangerous design (for demonstration): returns modifiable reference
    int& badGetBalance() { return balance; }

private:
    int balance{0};
};

int main() {
    std::cout << "Entering outer scope\n";
    GuardedAccount acc1(100);
    GuardedAccount acc2(250);

    // Memberwise assignment:
    acc1 = acc2;
    std::cout << "After acc1 = acc2, acc1 balance: " << acc1.getBalance() << "\n";

    // Demonstrating the reference leak trap:
    int& ref = acc1.badGetBalance();
    ref = 999; // Alters private member directly!
    std::cout << "Corrupted acc1 balance via ref: " << acc1.getBalance() << "\n";

    std::cout << "Exiting outer scope\n";
    return 0;
}

#include <iostream>

class ServerCounter {
public:
    ServerCounter(int id = 0) : serverId(id) {
        ++totalServers;
    }

    ~ServerCounter() {
        --totalServers;
    }

    // Cascaded member function returning *this
    ServerCounter& setId(int id) {
        this->serverId = id; // explicit this pointer disambiguation
        return *this;
    }

    // const member function
    int getId() const {
        return serverId;
    }

    // static member function
    static int getActiveCount() {
        return totalServers; // can only access static members directly
    }

private:
    int serverId;
    static inline int totalServers = 0; // C++17 inline static initialization
};

int main() {
    std::cout << "Initial servers: " << ServerCounter::getActiveCount() << "\n";

    ServerCounter s1;
    // Cascaded call using returned *this reference
    s1.setId(101);

    const ServerCounter s2(202); // const object
    std::cout << "s2 ID: " << s2.getId() << "\n"; // OK: const function
    // s2.setId(303); // Error: cannot call non-const function on const object

    std::cout << "Active servers after s1 & s2: " << ServerCounter::getActiveCount() << "\n";
    return 0;
}
